    const matrix = svg.current?.getScreenCTM();
    if (!matrix || !Number.isFinite(matrix.a) || matrix.a <= 0) return null;
    return new DOMPoint(e.clientX, e.clientY).matrixTransform(matrix.inverse());
  }
