.imageCrop{padding:clamp(12px,2vw,24px);background:#f3eddf;color:#263f3c;border:1px solid #b9c6b6;border-radius:12px;font-size:16px;line-height:1.65}
.imageCrop header>span{font-size:.72rem;letter-spacing:.14em;color:#536d62}.imageCrop h4{font-size:clamp(1.4rem,3vw,2rem);margin:.4em 0}.imageCrop h5{font-size:1rem;margin:.8em 0}.imageCrop p{margin:.6em 0}
.imageCrop .icToolbar{display:flex;flex-wrap:wrap;gap:10px;align-items:end}.imageCrop label{margin:0;gap:4px}.imageCrop button{background:#315e57;color:#fff9ed;border-color:#315e57;min-height:44px}.imageCrop button:disabled{opacity:.45}.imageCrop input,.imageCrop select{color:#263f3c;background:#fffdf5;border:1px solid #879c8b;border-radius:5px;padding:6px;min-height:44px;font:inherit}.imageCrop input[readonly]{background:#e4e8dc}.imageCrop :is(button,input,select,[tabindex]):focus-visible{outline:3px solid #a64b26;outline-offset:3px}
.icState{padding:9px 12px;border-left:4px solid #b56d4c;background:#e5e6d6}.icWorkspace{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:20px}.icMat{padding:44px;background:#e1dfcc;border-radius:8px;margin:12px 0}.icCanvas{position:relative;outline-offset:6px;touch-action:pan-y pinch-zoom}.icSource{display:block;width:100%;height:auto;aspect-ratio:10/7;overflow:hidden;user-select:none}.icSource [data-crop-drag]{cursor:move;touch-action:pinch-zoom}.imageCrop .icHandle{position:absolute;width:44px;height:44px;min-height:44px;padding:0;border:2px solid #fbf2ce;background:#315e57;border-radius:10px;touch-action:pinch-zoom;line-height:1;z-index:1}.icHandle.nw{transform:translate(-100%,-100%);cursor:nw-resize}.icHandle.ne{transform:translate(0,-100%);cursor:ne-resize}.icHandle.sw{transform:translate(-100%,0);cursor:sw-resize}.icHandle.se{cursor:se-resize}.icHandle span{pointer-events:none;font-size:23px}
.icDirections{display:flex;flex-wrap:wrap;gap:6px}.icResult{margin:0 0 14px;padding:10px;background:#fffaf0;border:1px solid #becab7;border-radius:8px}.icResult figcaption{font-weight:bold;display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap}.icResult figcaption span{font-size:.8em;color:#536d62}.icResult svg{display:block;width:100%;height:auto;max-height:none;margin-top:8px;overflow:hidden}.icResult p{font-size:.78rem;font-variant-numeric:tabular-nums}.icNumbers fieldset{border:1px solid #879c8b;border-radius:8px;padding:12px;margin:12px 0}.icNumbers fieldset>div{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;align-items:end}.icNumbers button{grid-column:1/-1}.icNumbers p{font-size:.85rem}.imageCrop [role=status]{border-top:1px solid #b5c2ad;padding-top:12px}
@media(max-width:900px){.icWorkspace{grid-template-columns:1fr}.icResults{display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:start}.icResults h5{grid-column:1/-1}.icNumbers fieldset>div{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:500px){.icResults{grid-template-columns:1fr}.icMat{margin-inline:-6px}.imageCrop .icToolbar>button{flex:1 1 120px}}
@media(prefers-reduced-motion:reduce){.imageCrop *{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
